  (* [comment removed for export] *)
  Lemma swin_here : swin_ok (kn ch) (a_vis ch) = true.
  Proof. pose proof swin_check_ok as H. unfold swin_check in H. exact (BoMainCells.all_holes_here sp0 brk0 h ch Hh _ H). Qed.
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Logic.ex Sort Prop.

  (* [comment removed for export] *)
  Lemma vis_window_full : forall p, In p (a_vis ch) ->
